(function(){window.showTab=function(e){document.querySelectorAll(".action-section__tab-panel").forEach(o=>o.classList.remove("active")),document.querySelectorAll(".action-section__tab-btn").forEach(o=>o.classList.remove("active"));const n=document.getElementById("tab-"+e);n&&n.classList.add("active");const t=document.querySelector(`.action-section__tab-btn[data-tab="${e}"]`);t&&t.classList.add("active")},window.copyText=function(e){const n=document.getElementById(e);n&&navigator.clipboard.writeText(n.innerText).then(()=>{const t=n.parentElement.querySelector(".action-section__copy-btn");t&&(t.textContent="✓ Copied!",t.classList.add("copied"),setTimeout(()=>{t.textContent="Copy Text",t.classList.remove("copied")},2e3))})},document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll(".action-section__tab-btn").forEach(e=>{e.addEventListener("click",()=>showTab(e.dataset.tab))})})})();
